from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Split the grid at its solid separator.
    col_sep = next(
        (c for c in range(w)
         if all(grid[r][c] == grid[0][c] for r in range(h))),
        None
    )

    if col_sep is not None:
        a = [row[:col_sep] for row in grid]
        b = [row[col_sep + 1:] for row in grid]
    else:
        row_sep = next(
            r for r in range(h)
            if all(value == grid[r][0] for value in grid[r])
        )
        a, b = grid[:row_sep], grid[row_sep + 1:]

    ca = Counter(x for row in a for x in row)
    cb = Counter(x for row in b for x in row)
    shared = set(ca) & set(cb)
    color = next(iter(shared))

    bg_a = ca.most_common(1)[0][0]
    bg_b = cb.most_common(1)[0][0]
    both_backgrounds = color == bg_a and color == bg_b

    out = []
    for r in range(len(a)):
        row = []
        for c in range(len(a[0])):
            overlap = a[r][c] == color and b[r][c] == color
            if both_backgrounds:
                row.append(color if not overlap else 3)
            else:
                row.append(3 if overlap else color)
        out.append(row)
    return out
