from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid separator column or row.
    sep_col = next(
        (c for c in range(w)
         if all(grid[r][c] == grid[0][c] for r in range(h))),
        None
    )

    if sep_col is not None:
        first = [row[:sep_col] for row in grid]
        second = [row[sep_col + 1:] for row in grid]
    else:
        sep_row = next(
            r for r in range(h)
            if all(x == grid[r][0] for x in grid[r])
        )
        first, second = grid[:sep_row], grid[sep_row + 1:]

    shared = set(x for row in first for x in row) & set(
        x for row in second for x in row
    )
    background = next(iter(shared))

    return [
        [3 if first[r][c] == second[r][c] else background
         for c in range(len(first[0]))]
        for r in range(len(first))
    ]
